 c['docs']=[doc('Şirket dosyası / '+name,story),doc('Organizasyon ve görev çerçevesi','Yürürlükteki görev dağılımından alınan kayıt. Tablodaki kişiler kurgusaldır. Vaka kapsamındaki görevin, ilgili karar toplantısının dosyasını ve önerisini hazırlamaktır. Nihai onaylar aşağıdaki yapı içinde verilir.',['Birim / kişi','Sorumluluk','Karar / onay alanı'],org)]+c['docs']+[doc(history_title,'Aşağıdaki kayıtlar bilgi dosyasının dönemsel ekidir. Ayrı bir tablo olduğu için başka belgelerdeki tutar veya adetlerin üzerine kendiliğinden eklenmez. Dönem ve kapsam sütunları kayıtların ait olduğu grubu gösterir.',hh,hr),doc(detail_title,'İlgili bölümün çalışma sisteminden alınmış kurgusal kayıtlar. Açıklama alanları kayıt sahibinin dönem içindeki notlarıdır; yönetim tarafından doğrulanmış neden sonuç değerlendirmesi değildir.',dh,dr),doc('İç yazışmalar / toplantı öncesi',mails),doc('İşleyiş ve toplantı kayıtları',policy)]
