'Bugün çıkış takvimi',['Grup','Küçük','Büyük','Taşıyıcı masası hedefi'],[['G1',180,40,'11.00'],['G2',150,50,'12.30'],['G3',170,60,'14.00'],['G4',160,50,'15.00'],['G5',140,50,'16.00'],['G6',100,50,'17.30']],
